import{z as l,x as s,o as B,c as d,q as t,j as o,D as n,d as a,s as A,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"事件风险与拥挤","description":"","frontmatter":{"title":"事件风险与拥挤","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-event-risk-crowding.md","filePath":"quant/ed-event-risk-crowding.md","lastUpdated":1791063341000}'),p={name:"quant/ed-event-risk-crowding.md"};function m(u,E,C,D,h,f){const r=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="事件风险与拥挤" tabindex="-1">事件风险与拥挤 <a class="header-anchor" href="#事件风险与拥挤" aria-label="Permalink to &quot;事件风险与拥挤&quot;">​</a></h1><div class="epigraph"><p>可预测的日历吸引资本，资本压缩溢价，溢价消失的日子风险照旧在场；拥挤把事件策略的尾部连成一片。</p><footer>—— 据 Shleifer and Vishny, Journal of Finance, 1997；Khandani and Lo, Journal of Portfolio Management, 2011 整理</footer></div><p><a href="/quant/ed-eventstudy-micro-app">上一课</a>把微观痕迹测成速率表；本课进入风控。事件策略的风险分三层：单事件的二值性、事件间的相关、拥挤。原型在<a href="/quant/merger-arbitrage">并购套利</a>里已经给过：完成收息，失败左尾成簇，且失败在市场下跌时更密。本课把原型推广到全谱系，三层各写成限额与监测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><strong>第一层：单事件是 Bernoulli。</strong> 一次并购、一次审核、一次细则落地，结果二值或近二值，收益分布由少数坏结果主导。按日历日算夏普，会把二值风险摊薄成看似平滑的日息；仓位若按「平均完成率」设定，左尾一到就穿透。<strong>第二层：事件之间相关。</strong> 同一宏观状态下失败成簇（并购失败与市场 beta 的非线性），同一窗口内事件扎堆（财报季、生效日、政策窗），持仓共享同一条日历——相关性不来自共同因子暴露，而来自共同的事件日。<strong>第三层：拥挤。</strong> 日历公开使 alpha 可复制，复制不需要模型只要时间表；资本涌入压缩溢价（并购价差随资本进入变窄），溢价变薄使杠杆被用来维持收益，杠杆又使平仓在事件日同向发生。</p><p><span class="marginnote">术语翻译：Bernoulli（伯努利）就是「一次只出两个结果」的随机试验，像抛硬币——完成或失败、通过或否决。把这种二值风险按日历日摊开算夏普，坏结果会被平均稀释成风平浪静，直到事件日一次性兑现。</span></p><p><span class="marginnote">Khandani 与 Lo（2011）复盘 2007 年 8 月：互不知名的多数量化策略在几日内同向巨亏——没有共同基本面，只有共同风格与共同杠杆，平仓本身制造了相关性。事件日就是「被迫同向」的预定时刻。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>单事件按左尾设仓。</strong> 每类事件先写「坏结果」清单与其价值路径：并购写失败价值与市场状态的相关，调仓写名单错判与流动性消失，宏观写方向错误的跳变。仓位由坏结果情景决定，不由期望收益决定；同时存在 \\(n\\) 笔未决事件时，左尾按「坏结果同时发生 \\(k\\) 个」的分布算，不做独立近似——它们共享状态变量。</p><p><span class="marginnote">数字实例：10 笔未决并购，单笔失败率各 5%。若彼此独立，「至少两笔同时失败」的概率约 8.6%；但失败概率会随市场下跌共同上升（衰退日接近翻倍），真实左尾远超独立近似——这正是仓位必须按共同状态变量的联合分布算、而不能把 \\(n\\) 笔当独立抛硬币的原因。</span></p><p><strong>日历的组合视角。</strong> 把持仓的事件日投影到一条时间线：财报扎堆周、生效日、发布周的暴露集中度单独限额；同窗不同事件的同向暴露（都在赌波动回落）按事件 beta 加总。这是事件策略独有的风控维度：因子看静态暴露，事件看时间线上的暴露序列。</p><p><strong>拥挤的三只表。</strong> 监测宣布效应的时序衰减（宣布窗收益逐年变薄）、同类资本的规模代理（容量、专户数、价差分位）、溢价相对自身历史的分位。三只表同向恶化即降杠杆，而不是等事件日来教育。</p>',12)),(B(),o(i,null,{default:n(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREM%5B%22%E6%BA%A2%E4%BB%B7%E5%AD%98%E5%9C%A8%22%5D%20--%3E%20CAP%5B%22%E8%B5%84%E6%9C%AC%E6%B6%8C%E5%85%A5%EF%BC%9A%E6%97%A5%E5%8E%86%E5%85%AC%E5%BC%80%E5%8F%AF%E5%A4%8D%E5%88%B6%22%5D%0A%20%20CAP%20--%3E%20THIN%5B%22%E6%BA%A2%E4%BB%B7%E5%8E%8B%E7%BC%A9%EF%BC%9A%E6%9D%A0%E6%9D%86%E7%BB%B4%E6%8C%81%E6%94%B6%E7%9B%8A%22%5D%0A%20%20THIN%20--%3E%20EVBAD%5B%22%E4%BA%8B%E4%BB%B6%E6%97%A5%E6%8D%9F%E5%A4%B1%EF%BC%9A%E5%B7%A6%E5%B0%BE%E5%85%91%E7%8E%B0%22%5D%0A%20%20EVBAD%20--%3E%20UNWIND%5B%22%E5%90%8C%E5%90%91%E5%B9%B3%E4%BB%93%EF%BC%9A%E7%9B%B8%E5%85%B3%E6%80%A7%E8%A2%AB%E5%88%B6%E9%80%A0%22%5D%0A%20%20UNWIND%20--%3E%20WIDE%5B%22%E4%BB%B7%E5%B7%AE%E8%B5%B0%E6%89%A9%20%E6%BA%A2%E4%BB%B7%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20WIDE%20--%3E%7C%22%E7%95%99%E7%BB%99%E6%9C%AA%E5%B9%B3%E4%BB%93%E8%80%85%22%7C%20THIN%0A%20%20MON%5B%22%E4%B8%89%E5%8F%AA%E8%A1%A8%EF%BC%9A%E8%A1%B0%E5%87%8F%20%E8%B5%84%E6%9C%AC%20%E5%88%86%E4%BD%8D%22%5D%20--%3E%20CAP%0A"})]),fallback:n(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"正反馈环写在图里：溢价吸引资本，资本压缩溢价，压缩后用杠杆补收益，事件日损失触发同向减仓，减仓把价差重新走扩——回补由没平仓的人赚，平仓的人承担最深的一段。Shleifer 与 Vishny（1997）把这写成套利的边界：管理他人资本者，在价差最走扩时恰逢赎回与保证金，被迫在最坏时刻退出——事件策略的退出时刻由日历预定，边界更紧。Stein（2009）补上另一面：老练投资者彼此知晓对方存在，进出决策互相内生化——拥挤不是事故，是均衡性质。",-1)),E[5]||(E[5]=e("p",null,[a("含义落在退出规则上：止损必须定义在"),e("strong",null,"信息"),a("上——完成概率的恶化、规则文本的变化、载荷与预期的结构性偏离——而不是 \\(|z|\\gt 2\\sigma\\) 这类价格统计量。价格走扩可能是坏消息，也可能是拥挤的同向平仓；前者认赔，后者或是加仓机会，区分的唯一线索是信息面有没有变。")],-1)),(B(),o(i,null,{default:n(()=>[A(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPREAD%5B%22%E4%BB%B7%E5%B7%AE%E6%88%96%E6%8C%81%E4%BB%93%E8%B5%B0%E6%89%A9%22%5D%20--%3E%20Q1%7B%22%E4%BF%A1%E6%81%AF%E9%9D%A2%E5%8F%98%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20Q1%20--%20%22%E5%8F%98%E4%BA%86%3A%20%E5%AE%8C%E6%88%90%E6%A6%82%E7%8E%87%E6%81%B6%E5%8C%96%22%20--%3E%20LOSS%5B%22%E8%AE%A4%E8%B5%94%E9%80%80%E5%87%BA%22%5D%0A%20%20Q1%20--%20%22%E6%B2%A1%E5%8F%98%22%20--%3E%20Q2%7B%22%E4%B8%89%E5%8F%AA%E8%A1%A8%E5%90%8C%E5%90%91%E6%81%B6%E5%8C%96%3F%22%7D%0A%20%20Q2%20--%20%22%E6%98%AF%3A%20%E6%8B%A5%E6%8C%A4%E5%8E%BB%E6%9D%A0%E6%9D%86%E4%B8%AD%22%20--%3E%20HOLD%5B%22%E5%8C%BA%E5%88%86%E5%AF%B9%E5%BE%85%3A%20%E6%88%96%E6%98%AF%E5%9B%9E%E8%A1%A5%E6%9C%BA%E4%BC%9A%22%5D%0A%20%20Q2%20--%20%22%E5%90%A6%22%20--%3E%20CHK%5B%22%E6%8C%89%E5%8E%9F%E9%99%90%E9%A2%9D%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%22%5D%0A"})]),fallback:n(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">常见误区：看到价差走扩就机械止损。走扩可能是坏消息（完成概率真的降了），也可能只是拥挤的同向平仓把价格推离基本面；前者该认赔，后者可能是加仓机会。二者价格长得一样，唯一的分拣线索是信息面有没有实质变化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>拥挤不可直接观测，三只表都是代理，且在结构变化处失灵——资本进入方式改变时，旧分位失效。溢价压缩不等于消失：把「有拥挤」当成「清空日历暴露」，是把风控做成择时。尾部对冲成本要计入事件收益：长期买保护的组合，账面与不对冲的同类不可比。压力日的相关性跳变，用平静期相关性做风险平价，会在最需要分散的日子发现分散不见了——事件组合的风险模型要用事件日样本估，而事件日样本恰恰最少。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层风险：单事件 Bernoulli、事件日的组合相关、拥挤的正反馈；各配各的限额。</li><li>仓位按坏结果情景设定，多事件的左尾按共同状态相关算，不按独立近似。</li><li>独有维度是时间线：事件日暴露集中度单独限额，不只看静态暴露。</li><li>拥挤用三只表监测：效应衰减、资本规模、溢价分位；同向恶化时降杠杆。</li><li>止损定义在信息上，不在价格统计量上；区分坏消息与拥挤平仓是难点。</li><li>出处：Shleifer and Vishny, <em>Journal of Finance</em>, 1997；Mitchell and Pulvino, <em>Journal of Finance</em>, 2001；Stein, <em>Journal of Finance</em>, 2009；Khandani and Lo, <em>Journal of Portfolio Management</em>, 2011。</li></ul>',5))])}const F=l(p,[["render",m]]);export{c as __pageData,F as default};
